        log.info("Last timestamp is negative");
        _lastTimestamp = 0;
    }
    if (timestamp <= _lastTimestamp) {
        log.warn("Timestamp is not greater than last timestamp");
        return false;
    }
    // Check if the message is not null or empty
    if (message == null || message.isEmpty()) {
        log.error("Message is null or empty");
        return false;
    }
    // If the message should be printed, set the last timestamp
    _lastTimestamp = timestamp;
    return true;
}

