/** 
 * <p>Check if a String ends with a specified suffix (optionally case insensitive).</p>
 * @see String#endsWith(String)
 * @param str  the String to check, may be null
 * @param suffix the suffix to find, may be null
 * @param ignoreCase inidicates whether the compare should ignore case(case insensitive) or not.
 * @return <code>true</code> if the String starts with the prefix orboth <code>null</code>
 */ private static boolean endsWith(final String str,final String suffix,final boolean ignoreCase) {
  // If both str and suffix are null, return true
  if (str == null && suffix == null) {
    return true;
  }

  // If either str or suffix is null, return false
  if (str == null || suffix == null) {
    return false;
  }

  // If the suffix length is greater than the str length, return false
  if (suffix.length() > str.length()) {
    return false;
  }

  // If the suffix is longer than the str, return false
  if (str.length() < suffix.length()) {
    return false;
  }

  // Check the characters of str from the end of the String
  for (int i = suffix.length() - 1; i >= 0; i--) {
    // If the characters are not equal, return false
    if (str.charAt(i) != suffix.charAt(i)) {
      if (ignoreCase) {
        // If the characters in str and suffix are not equal, but case insensitive comparison returns true, return true
        if (Character.toLowerCase(str.charAt(i)) == Character.toLowerCase(suffix.charAt(i))) {
          return true;
        }
      } else {
        return false;
      }
    }
  }

  return true;
}

