public static Character[] nullToEmpty(final Character[] array) {
    if (array == null) {
        return EMPTY_CHARACTER_ARRAY;
    }

    if (array.length == 0) {
        return array;
    }

    // Create a copy of the input array
    final Character[] copy = Arrays.copyOf(array, array.length);

    // Replace all nulls with empty characters in the copy
    for (int i = 0; i < copy.length; i++) {
        if (copy[i] == null) {
            copy[i] = Character.MIN_VALUE;
        }
    }

    // Override the input array with the copy
    array = copy;

    return array;
}

