    // Since the output will be a string, we can initialize an empty string builder.
    final StringBuilder builder = new StringBuilder();

    // Iterate through the input string, starting from the first index.
    for (int i = 0; i < len; i++) {
        // Get the current character from the input string.
        final char c = s.charAt(i);

        // If the character is not a whitespace, append it to the output string builder.
        if (!Character.isWhitespace(c)) {
            builder.append(c);
        }
    }

    // Return the decoded string.
    return builder.toString();
}

