    // Create a new array of the appropriate size
    String[] result = new String[size];

    // Iterate over the collection and add each element to the array
    int index = 0;
    for (Object element : collection) {
        // Check if the element is null
        if (element == null) {
            throw new NullPointerException("The collection must not contain null elements");
