        return new String[0];
    }

    // Get the size of the collection and create a new array with the same size
    int size = collection.size();
    String[] result = new String[size];

    // Iterate over the collection and add the elements to the array
    int i = 0;
    for (Object element : collection) {
        if (element != null) {
