GraphPath<V, E> function(Set<E> tour, Graph<V, E> graph) {
    // Initialize the graph path
    GraphPath<V, E> result = new GraphPath<V, E>();

    // Iterate over the edges in the tour
    for (E edge : tour) {
        // Get the starting and ending vertices of the edge
        V startingVertex = graph.getEdgeStart(edge);
        V endingVertex = graph.getEdgeEnd(edge);

        // Add the edge to the graph path
        result.addEdge(edge);

        // If the edge connects to the starting vertex, drop it
        if (startingVertex == result.getStart()) {
            result.dropEdge(edge);
        }

        // If the edge connects to the ending vertex, drop it
        if (endingVertex == result.getEnd()) {
            result.dropEdge(edge);
        }
    }

    // Return the graph path
    return result;
}

