GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    // Step 1: Sort the edges based on their source vertex
    List<E> sortedEdges = tour.stream()
            .sorted(Comparator.comparing(graph::getEdgeSource))
            .collect(Collectors.toList());

    // Step 2: Create a new path with the same starting vertex as the first edge
    GraphPath<V, E> path = graph.createPath(sortedEdges.get(0).getSourceVertex());

    // Step 3: Iterate over the sorted edges and add them to the path
    for (int i = 1; i < sortedEdges.size(); i++) {
        E edge = sortedEdges.get(i);
        path.addEdge(edge);
    }

    // Step 4: Return the completed path
    return path;
}

