 * Check whether the subgraph of <code>graph</code> induced by the given <code>vertices</code> is complete, i.e. a clique.
 * @param graph the graph.
 * @param vertices the vertices to induce the subgraph from.
 * @return true if the induced subgraph is a clique.
 */
private static <V,E>boolean isClique(Graph<V,E> graph,Set<V> vertices){
for(V vertex : vertices) {
Set<V> reachableVertexes = new HashSet<>();
reachableVertexes.add(vertex);
boolean isClique = true;
graph.getVertices().stream().forEach(v -> {
if(vertices.contains(v)) {
if(!reachableVertexes.contains(v)) {
return false;
}
} else {
if(vertices.contains(graph.getE neighbour(v))) {
reachableVertexes.add(graph.getE neighbour(v));
}
}
});
return isClique;
}
