public static Meteor lookup(HttpServletRequest r) {
  // Get the AtmosphereResource from the HttpServletRequest
  AtmosphereResource ar = r.getAtmosphereResource();

  // Check if the AtmosphereResource is active and has a valid connection
  if (ar != null && !ar.isDestroyed()) {
    // Get the Logger for the Meteor class
    Logger logger = Logger.getLogger(Meteor.class.getName() + ".lookup");

    // Check if the connection is still open
    if (!ar.getAtmosphereResource().getBroadcaster().isOpen()) {
      logger.info("Connection is no longer open, destroying the Meteor");
      return null;
    }

    // Get the Meteor instance from the AtmosphereResource
    Meteor meteor = r.getAtmosphereResource().getMeteor();

    // Check if the Meteor instance is null
    if (meteor == null) {
      logger.info("Cannot find a Meteor instance for this AtmosphereResource");
      return null;
    }

    // Return the Meteor instance
    return meteor;
  } else {
    logger.info("Cannot find a valid AtmosphereResource for this request");
    return null;
  }
}

