    AtomicBoolean isDestroyed = new AtomicBoolean(false);

    // Add an AtmosphereResourceEventListener to the resource and suspend the connection
    // when the WebSocket connection is closed or drops
    r.addEventListener(new AtmosphereResourceListener() {
        @Override
        public void onDisconnect(AtmosphereResourceEvent event) {
            if (isSuspended.get()) {
                // Resume the connection if it was previously suspended
                event.getResource().resume();
            }
            isDestroyed.set(true);
        }

        @Override
        public void onResponse(AtmosphereResourceEvent event) {
            if (event.getMessage() instanceof WebSocket) {
