public static String applyRelativePath(String path, String relativePath) {
    // Split the path into its individual components
    String[] pathComponents = path.split("/");
    // Split the relative path into its individual components
    String[] relativePathComponents = relativePath.split("/");

    // Iterate through the relative path components
    for (String component : relativePathComponents) {
        // Check if the component is a filename
        if (component.contains(".")) {
            // If so, replace the filename with the component from the relative path
            pathComponents[pathComponents.length - 1] = component;
        } else {
            // If not, add the component to the end of the path
            String[] newPathComponents = new String[pathComponents.length + 1];
            System.arraycopy(pathComponents, 0, newPathComponents, 0, pathComponents.length);
            newPathComponents[pathComponents.length] = component;
            pathComponents = newPathComponents;
        }
    }

    // Join the components into a single path string
    StringBuilder pathString = new StringBuilder();
    for (String component : pathComponents) {
        pathString.append(component).append("/");
    }
    // Remove the trailing slash
    pathString.deleteCharAt(pathString.length() - 1);

    // Return the resulting path
    return pathString.toString();
}

