public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relative path cannot be null");
    }

    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");
    List<String> newPathParts = new ArrayList<>();

    int i = 0;
    while (i < relativePathParts.length) {
        if (relativePathParts[i].equals("..")) {
            // Go up a directory
            if (i == 0) {
                throw new IllegalArgumentException("Invalid relative path: cannot go up a directory from the root");
            }
            --i;
        } else if (relativePathParts[i].equals(".")) {
            // Stay in the same directory
            i++;
        } else {
            newPathParts.add(relativePathParts[i]);
            i++;
        }
    }

    String result = "";
    for (String part : newPathParts) {
        result += part + "/";
    }
    return result;
}

