public Class findClass(String className) throws ClassNotFoundException {
    Class<?> cls;
    // Check if the class has been loaded already
    cls = Class.forName(className);
    if (cls != null) {
        return cls;
    }

    // Split the class name into tokens
    String[] tokens = className.split("\\.");

    // Traverse the class hierarchy
    for (int i = 0; i < tokens.length; i++) {
        // Get the current package name
        String packageName = "";
        for (int j = 0; j < i; j++) {
            packageName += tokens[j] + ".";
        }

        // Load the class
        cls = Class.forName(packageName + tokens[i]);
        if (cls != null) {
            return cls;
        }
    }

    // If we reach here, the class could not be found
    throw new ClassNotFoundException("Class " + className + " could not be found");
}

