        // If the LogTable is not yet initialized, do nothing
        if (logTable == null) {
            return;
        }

        // Add the message to the LogTable
        logTable.addMessage(message);

        // Scroll the LogTable to the bottom
        logTable.scrollToLastLine();
    });
