    // Re-format the time bucket based on the dayStep
    int year = (int) (timeBucket / 100000000);
    int month = (int) ((timeBucket / 1000000) % 100);
    int day = (int) (timeBucket % 1000000);

    int newYear = year;
    int newMonth = month;
    int newDay = day;

    if (dayStep == 10) {
        newYear = (int) (year / 10) * 10;
        newMonth = (int) (month / 10) * 10;
        newDay = (int) (day / 10) * 10;
    } else if (dayStep == 11) {
        newYear = (int) (year / 10) * 10;
        newMonth = (int) (month / 10) * 10;
        newDay = (int) (day / 100) * 100;
    } else if (dayStep == 12) {
