    List<ThreadSnapshot> snapshots = new ArrayList<>();
    BufferedReader reader = new BufferedReader(new FileReader(file));

    String line;
    while ((line = reader.readLine()) != null) {
        if (line.startsWith("#") || line.isEmpty()) {
            continue;
        }
        String[] parts = line.split(" ");
        if (parts.length != 5) {
            throw new IOException("Invalid format: " + line);
        }
        long time = Long.parseLong(parts[0]);
        int threadId = Integer.parseInt(parts[1]);
        String threadName = parts[2];
        String groupName = parts[3];
        int depth = Integer.parseInt(parts[4]);

        ProfileAnalyzeTimeRange timeRange = timeRanges.stream().filter(tr -> tr.getStartMillis() <= time && tr.getEndMillis() >= time).findFirst().orElse(null);
        if (timeRange != null) {
            ThreadSnapshot snapshot = new ThreadSnapshot(threadId, threadName, groupName, depth);
            snapshots.add(snapshot);
        }
    }

    return snapshots;
}

